window.__BLOCK_BLAST__={stages:STAGES,shapes:SHAPES,terrain:TERRAIN,dirtBlock:DIRT_BLOCK,fits,placements,trayCompletable,objectiveMet,start,place,previewAt,getState:()=>({currentStage,selectedStage,endless,grid:[...grid],terrain:[...terrain],tray:tray.map(s=>({...s,cells:clone(s.cells)})),score,lines,sets,comboStreak,terrainCleared,dirtCleared,iceCleared,gems,colorCleared,unlocked,preview:[...preview],previewAnchor,previewIsValid,flashCells:[...flashCells],effectLines:effectLines.map(line=>({...line}))}),loadFixture:fixture=>{resetRunAsync();clearEffectState();clearScorePop();comboStreak=0;grid=[...(fixture.grid||Array(64).fill(null))];terrain=[...(fixture.terrain||Array(64).fill(0))];for(let index=0;index<64;index++)if(terrain[index]===TERRAIN.DIRT&&grid[index]==null)grid[index]=DIRT_BLOCK;tray=(fixture.tray||[SHAPES[0]]).map((shape,index)=>({...shape,color:index%COLORS.length,used:false,cells:clone(shape.cells)}));selected=-1;preview=[];previewAnchor=-1;previewIsValid=false;score=lines=terrainCleared=dirtCleared=iceCleared=gems=colorCleared=0;sets=1;lastTrayHadLarge=false;setsSinceLarge=setsSinceNine=0;render();},generatorProbe:(g,tr,n=30,stage=currentStage)=>{const old={grid,terrain,currentStage,generation,tray,sets,lastTrayHadLarge,setsSinceLarge,setsSinceNine,endless};grid=[...g];terrain=[...tr];currentStage=stage;generation=0;lastTrayHadLarge=false;setsSinceLarge=setsSinceNine=0;endless=false;const groups=[];for(let i=0;i<n;i++){const generated=generateTray();groups.push({generated,complete:generated&&trayCompletable(tray),pieces:tray.map(s=>({id:s.id,size:s.size,color:s.color,fits:placements(s).length}))});}({grid,terrain,currentStage,generation,tray,sets,lastTrayHadLarge,setsSinceLarge,setsSinceNine,endless}=old);return groups;},endlessGeneratorProbe:(n=80)=>{const old={grid,terrain,currentStage,generation,tray,sets,lastTrayHadLarge,setsSinceLarge,setsSinceNine,endless,score};grid=Array(64).fill(null);terrain=Array(64).fill(0);currentStage=1;generation=sets=score=0;lastTrayHadLarge=false;setsSinceLarge=setsSinceNine=0;endless=true;const groups=[];for(let i=0;i<n;i++){const generated=generateTray();groups.push({generated,complete:generated&&trayCompletable(tray),pieces:tray.map(s=>({id:s.id,size:s.size,cells:s.cells.length}))});}({grid,terrain,currentStage,generation,tray,sets,lastTrayHadLarge,setsSinceLarge,setsSinceNine,endless,score}=old);return groups;}};
const blockBlastGetState=window.__BLOCK_BLAST__.getState;
window.__BLOCK_BLAST__.getState=()=>({...blockBlastGetState(),endlessBest});
window.__BLOCK_BLAST__.getEndlessBest=()=>endlessBest;
new MutationObserver(()=>{const card=$("stageRail")?.querySelector('.stage-card[aria-current="true"]');if(!card)return;const virtualIndex=Number(card.dataset.wpStageVirtualIndex),n=Number.isFinite(virtualIndex)?virtualIndex+1:+card.dataset.stage;syncStageSelection(n,false);}).observe($("stageRail"),{attributes:true,attributeFilter:["aria-current"],childList:true,subtree:true});
new MutationObserver(()=>{document.querySelectorAll("#pieceTray .piece").forEach((button,index)=>{const shape=tray[index];if(!shape)return;button.setAttribute("aria-label",shapeLabel(shape,index));button.setAttribute("aria-pressed",String(index===selected));button.title=shapeLabel(shape,index);button.querySelector(".piece-shape")?.setAttribute("aria-hidden","true");});}).observe($("pieceTray"),{childList:true,subtree:true});
new MutationObserver(()=>{const feedback=$("feedback");if(feedback?.textContent===t("invalid"))feedback.textContent=invalidFeedback();}).observe($("feedback"),{childList:true,characterData:true,subtree:true});
applyLocale();syncSound();setScreen("main");setTimeout(()=>{mountEndlessEntry();document.documentElement.dataset.gameReady="true";},0);
